import json, re

with open('vm_catalog.json') as f:
    cat = json.load(f)

def empty():
    return {"essence":[],"diesel":[],"hybride":[],"electrique":[],"gpl":[]}

def add(model, year, v, fuel):
    if year not in model:
        model[year] = empty()
    if isinstance(model[year], dict) and fuel in model[year]:
        if v not in model[year][fuel]:
            model[year][fuel].append(v)

FUEL_KEYS = ['essence','diesel','hybride','electrique','gpl']
def clean_parasites(model):
    for k in FUEL_KEYS:
        model.pop(k, None)

def year_total(model):
    return sum(len(vs) for k,v in model.items() if isinstance(v,dict) for vs in v.values())

# ── Yaris 3 ──────────────────────────────────────────────
def clean_y3(s):
    s = s.strip()
    prev = None
    while prev != s:
        prev = s
        s = re.sub(r'^III\s+', '', s).strip()
        s = re.sub(r'^\(\d+\)\s+', '', s).strip()
    return re.sub(r'\s+\d+P\b', '', s).strip()

def fuel_y3(v):
    u = v.upper()
    if 'D-4D' in u or 'D4D' in u: return 'diesel'
    if 'HYBRID' in u: return 'hybride'
    return 'essence'

y3 = cat['TOYOTA']['Yaris 3']
clean_parasites(y3)

