# ── Yaris 4 ──────────────────────────────────────────────
def clean_y4(s):
    s = s.strip()
    prev = None
    while prev != s:
        prev = s
        s = re.sub(r'^IV\s*', '', s).strip()
        s = re.sub(r'^\(\d+\)\s+', '', s).strip()
    return s

def fuel_y4(v):
    u = v.upper()
    if 'HYBRIDE' in u or re.search(r'\d+H\b', u): return 'hybride'
    return 'essence'

y4 = cat['TOYOTA']['Yaris 4']
clean_parasites(y4)

